const r = $json;
const html = `<div style="font-family:Arial,sans-serif;max-width:720px">
<h2>Cold-Chain SLA Report, ${r.report_date}</h2>
<p><b>${r.tickets_24h}</b> tickets in last 24h (P1: ${r.p1_count}, P2: ${r.p2_count}, P3: ${r.p3_count})<br>
SLA met: <b>${r.sla_met_pct}%</b> | Breaches: <b>${r.breaches}</b><br>
Avg time to acknowledge: ${r.avg_time_to_accept_min} min | Avg time to site: ${r.avg_time_to_site_min} min</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px">
<tr style="background:#eee"><th>Ticket</th><th>Client</th><th>Severity</th><th>Status</th><th>Ack (min)</th><th>On-site (min)</th><th>SLA</th></tr>
${r.detail_rows || '<tr><td colspan="7">No tickets in the last 24h</td></tr>'}</table></div>`;
return [{ json: { ...r, html } }];

const all = $input.all().map(i => i.json).filter(t => t.ticket_id);
const since = Date.now() - 24 * 3600000, now = Date.now();
const rows = all.filter(t => new Date(t.timestamp_in).getTime() >= since);
const mins = (a, b) => (a && b) ? (new Date(a) - new Date(b)) / 60000 : null;
const avg = arr => { const v = arr.filter(x => x !== null && !isNaN(x)); return v.length ? +(v.reduce((s, x) => s + x, 0) / v.length).toFixed(1) : 0; };
const met = rows.filter(t => t.resolved_at ? new Date(t.resolved_at) <= new Date(t.sla_deadline) : now <= new Date(t.sla_deadline)).length;
const count = s => rows.filter(t => t.severity_level === s).length;
const detail = rows.map(t => `<tr><td>${t.ticket_id}</td><td>${t.client_id}</td><td>${t.severity_level}</td><td>${t.status}</td><td>${(mins(t.accepted_at, t.timestamp_in) ?? '-')}</td><td>${(mins(t.on_site_at, t.timestamp_in) ?? '-')}</td><td>${t.breach_notified === 'YES' ? 'BREACHED' : 'OK'}</td></tr>`).join('');
return [{ json: {
  report_date: new Date().toISOString().slice(0, 10), tickets_24h: rows.length,
  p1_count: count('P1_CRITICAL'), p2_count: count('P2_HIGH'), p3_count: count('P3_NORMAL'),
  avg_time_to_accept_min: avg(rows.map(t => mins(t.accepted_at, t.timestamp_in))),
  avg_time_to_site_min: avg(rows.map(t => mins(t.on_site_at, t.timestamp_in))),
  sla_met_pct: rows.length ? Math.round(met / rows.length * 100) : 100,
  breaches: rows.filter(t => t.breach_notified === 'YES').length, detail_rows: detail } }];

const cfg = $('Set Heartbeat Configuration').first().json;
const tickets = $('Fetch All Ticket Data').all().map(i => i.json).filter(t => t.ticket_id);
const techs = $('Retrieve Technician Roster').all().map(i => i.json).filter(t => t.tech_id);
const now = Date.now(), nowIso = new Date(now).toISOString();
const ackMs = Number(cfg.ack_timeout_min || 10) * 60000;
const busy = new Set();
const out = [];
const twiml = m => `<Response><Say voice="alice">${String(m).replace(/[<>&]/g, ' ')}</Say></Response>`;
const link = (t, tech, a) => `${cfg.base_url}/tech-ack?ticket_id=${t.ticket_id}&tech_id=${tech}&action=${a}`;

for (const t of tickets) {
  const st = String(t.status).toUpperCase();
  if (st === 'RESOLVED') continue;
  const start = new Date(t.timestamp_in).getTime();
  const deadline = new Date(t.sla_deadline).getTime();
  const elapsedMin = Math.round((now - start) / 60000);
  const disp = new Date(t.dispatched_at || t.timestamp_in).getTime();

  const timedOut = ['DISPATCHED','BREACHED'].includes(st) && !t.accepted_at && (now - disp) > ackMs;
  let action = null;
  if (now > deadline && t.breach_notified !== 'YES') action = 'BREACH';
  else if (!t.assigned_tech_id || st === 'DECLINED' || st === 'UNASSIGNED' || timedOut) action = 'REASSIGN';
  else if ((now - start) >= (deadline - start) * 0.5 && st !== 'ON_SITE' && t.warn50_sent !== 'YES' && t.breach_notified !== 'YES') action = 'WARN_50';
  if (!action) continue;

  const base = { type: 'TICKET', ticket_id: t.ticket_id, status: st, assigned_tech_id: t.assigned_tech_id || '',
    dispatched_at: t.dispatched_at || '', reassign_count: Number(t.reassign_count || 0),
    excluded_tech_ids: t.excluded_tech_ids || '', warn50_sent: t.warn50_sent || 'NO',
    breach_notified: t.breach_notified || 'NO', last_alert_at: t.last_alert_at || '',
    elapsed_min: elapsedMin, alert_type: action, needs_call: false };

  if (action === 'BREACH') {
    out.push({ json: { ...base, status: 'BREACHED', breach_notified: 'YES', last_alert_at: nowIso,
      sms_to: cfg.ops_manager_phone,
      sms_body: `SLA BREACHED ${t.ticket_id} (${t.severity_level}) ${t.equipment_type}. ${elapsedMin} min elapsed, deadline was ${t.sla_deadline}.`,
      needs_call: true, call_to: cfg.oncall_lead_phone,
      call_twiml: twiml(`S L A breach on ticket ${t.ticket_id}. Immediate escalation required.`) } });
  } else if (action === 'WARN_50') {
    out.push({ json: { ...base, warn50_sent: 'YES', last_alert_at: nowIso,
      sms_to: cfg.ops_manager_phone,
      sms_body: `SLA 50% WARNING ${t.ticket_id} (${t.severity_level}). Tech ${t.assigned_tech_id} not on site yet. Status ${st}. Deadline ${t.sla_deadline}.` } });
  } else {
    const excluded = String(t.excluded_tech_ids || '').split(',').filter(Boolean);
    const old = t.assigned_tech_id || '';
    if (old) excluded.push(old);
    const pool = techs.filter(x => String(x.status).toUpperCase() === 'AVAILABLE' && !excluded.includes(x.tech_id) && !busy.has(x.tech_id));
    const pick = pool.find(x => x.current_zone === t.service_zone) || pool[0];
    if (pick) {
      busy.add(pick.tech_id);
      out.push({ json: { ...base, status: 'DISPATCHED', assigned_tech_id: pick.tech_id, dispatched_at: nowIso,
        reassign_count: base.reassign_count + 1, excluded_tech_ids: excluded.join(','), last_alert_at: nowIso,
        alert_type: 'REASSIGNED', sms_to: pick.phone,
        sms_body: `REASSIGNED ${t.severity_level} ${t.ticket_id} (${t.equipment_type}, ${t.alarm_code || 'no alarm code'}). Deadline ${t.sla_deadline}.\nACCEPT: ${link(t, pick.tech_id, 'accept')}\nDECLINE: ${link(t, pick.tech_id, 'decline')}\nON SITE: ${link(t, pick.tech_id, 'onsite')}\nRESOLVED: ${link(t, pick.tech_id, 'resolved')}`,
        needs_call: true, call_to: cfg.oncall_lead_phone,
        call_twiml: twiml(`Ticket ${t.ticket_id} was automatically reassigned to technician ${pick.name}. Previous technician did not respond.`) } });
      if (old) out.push({ json: { type: 'TECH', tech_id: old, status: 'UNRESPONSIVE', active_ticket_id: '' } });
      out.push({ json: { type: 'TECH', tech_id: pick.tech_id, status: 'ON_JOB', active_ticket_id: t.ticket_id } });
    } else {
      if (t.last_alert_at && (now - new Date(t.last_alert_at).getTime()) < 15 * 60000) continue;
      out.push({ json: { ...base, status: 'UNASSIGNED', assigned_tech_id: '', excluded_tech_ids: excluded.join(','),
        last_alert_at: nowIso, alert_type: 'NO_TECH_AVAILABLE', sms_to: cfg.oncall_lead_phone,
        sms_body: `NO TECH AVAILABLE for ${t.ticket_id} (${t.severity_level}) ${t.equipment_type}. ${elapsedMin} min elapsed. Dispatch manually.`,
        needs_call: true, call_to: cfg.oncall_lead_phone,
        call_twiml: twiml(`No technician available for ticket ${t.ticket_id}. Manual dispatch required.`) } });
      if (old) out.push({ json: { type: 'TECH', tech_id: old, status: 'UNRESPONSIVE', active_ticket_id: '' } });
    }
  }
}
return out;

const s = $('Calculate State Changes').first().json;
const html = `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cold-Chain Dispatch</title></head>
<body style="font-family:Arial,sans-serif;text-align:center;padding:48px 20px">
<h2>${s.event}</h2><p>Ticket <b>${s.ticket_id}</b> is now <b>${s.new_status}</b>.</p>
<p style="color:#666">${s.minutes_since_alert} min since alert. This action has been logged.</p></body></html>`;
return [{ json: { html } }];

const q = $('Decode Callback Data').first().json;
const t = $input.first().json;
if (!t.ticket_id) throw new Error('Ticket not found: ' + q.ticket_id);
if (String(t.assigned_tech_id) !== q.tech_id) throw new Error(`Stale link: ${q.tech_id} is not assigned to ${q.ticket_id}`);
const now = new Date(), iso = now.toISOString();
const mins = Math.round((now - new Date(t.timestamp_in)) / 60000);
const a = q.action;
const statusMap = { accept:'ACCEPTED', decline:'DECLINED', onsite:'ON_SITE', resolved:'RESOLVED' };
const excluded = String(t.excluded_tech_ids || '').split(',').filter(Boolean);
if (a === 'decline') excluded.push(q.tech_id);
const busy = (a === 'accept' || a === 'onsite');
const labels = { accept:'Technician ACKNOWLEDGED', decline:'Technician DECLINED', onsite:'Technician ON SITE', resolved:'Ticket RESOLVED' };
return [{ json: {
  ticket_id: t.ticket_id, tech_id: q.tech_id, action: a, new_status: statusMap[a],
  assigned_tech_id: a === 'decline' ? '' : t.assigned_tech_id,
  accepted_at: a === 'accept' ? iso : (t.accepted_at || ''),
  on_site_at: a === 'onsite' ? iso : (t.on_site_at || ''),
  resolved_at: a === 'resolved' ? iso : (t.resolved_at || ''),
  excluded_tech_ids: excluded.join(','),
  tech_status: busy ? 'ON_JOB' : 'AVAILABLE',
  tech_active_ticket: busy ? t.ticket_id : '',
  minutes_since_alert: mins,
  sla_met: now <= new Date(t.sla_deadline),
  event: labels[a]
}}];

const q = $json.query || {};
const action = String(q.action || '').toLowerCase();
if (!['accept','decline','onsite','resolved'].includes(action)) throw new Error('Invalid action: ' + action);
return [{ json: { ticket_id: String(q.ticket_id || ''), tech_id: String(q.tech_id || ''), action } }];

const d = $json;
const cfg = $('Set Intake Configuration').first().json;
const link = a => `${cfg.base_url}/tech-ack?ticket_id=${d.ticket_id}&tech_id=${d.primary_tech_id}&action=${a}`;
const tech_sms =
`${d.severity_level} ${d.ticket_id}
${d.company_name} (${d.facility_type})
${d.equipment_type}: ${d.current_temp_celsius}C (limit ${d.allowed_threshold_celsius}C, +${d.temp_delta_celsius} over setpoint)
Alarm: ${d.alarm_code || 'n/a'} | Product: ${d.product_class}
Site: ${d.site_address}
SLA deadline: ${d.sla_deadline}
ACCEPT: ${link('accept')}
DECLINE: ${link('decline')}
ON SITE: ${link('onsite')}
RESOLVED: ${link('resolved')}`;
const client_sms =
`Cold-chain alert received for ${d.equipment_type} (${d.current_temp_celsius}C). Ticket ${d.ticket_id}, priority ${d.severity_level}. Technician ${d.primary_tech_name} has been dispatched. Target on-site by ${d.sla_deadline}. Please move high-value stock if safe.`;
return [{ json: { ...d, tech_sms, client_sms } }];

const d = $('Identify Duplicate Alerts').first().json;
const techs = $input.all().map(i => i.json).filter(t => t.tech_id);
const need = String(d.default_certification || '').toLowerCase();
const eligible = techs
  .filter(t => String(t.status).toUpperCase() === 'AVAILABLE' && String(t.certifications || '').toLowerCase().includes(need))
  .sort((a, b) => (a.current_zone === d.service_zone ? 0 : 1) - (b.current_zone === d.service_zone ? 0 : 1));
const [p, b] = eligible;
return [{ json: { ...d, tech_found: !!p,
  primary_tech_id: p ? p.tech_id : '', primary_tech_name: p ? p.name : '', primary_tech_phone: p ? p.phone : '',
  backup_tech_id: b ? b.tech_id : '', match_pool_size: eligible.length } }];

const d = $('Assess Alert Severity').first().json;
const open = ['DISPATCHED','ACCEPTED','ON_SITE','DECLINED','UNASSIGNED','BREACHED'];
const dup = $input.all().map(i => i.json)
  .find(r => r.ticket_id && open.includes(String(r.status).toUpperCase()) && r.equipment_type === d.equipment_type);
return [{ json: { ...d, is_duplicate: !!dup, existing_ticket_id: dup ? dup.ticket_id : '' } }];

const d = $json;
const delta = d.temp_delta_celsius;
const highValue = ['PHARMA','BIOLOGICS','VACCINE','SEAFOOD'].includes(d.product_class);
const rate = Number(d.temp_rate_c_per_hr) || 0;
const h2b = (!d.sensor_fault && rate > 0) ? Math.max(0, (d.allowed_threshold_celsius - d.current_temp_celsius) / rate) : null;
let sev = 'P3_NORMAL', slaH = 24, reason = 'Sensor or non-thermal alarm';
if (!d.sensor_fault) {
  if (d.threshold_breached || delta > 5 || rate > 3 || (highValue && delta > 2)) {
    sev = 'P1_CRITICAL'; slaH = 2; reason = 'Threshold breach, rapid decay or high-value product';
  } else if (delta >= 2) {
    sev = 'P2_HIGH'; slaH = 4; reason = 'Degraded operation';
  }
}
const sla_hours = Math.min(slaH, d.contract_sla_hours);
const sla_deadline = new Date(new Date(d.timestamp_in).getTime() + sla_hours * 3600000).toISOString();
return [{ json: { ...d, severity_level: sev, severity_reason: reason, sla_hours, sla_deadline,
  hours_to_breach: h2b === null ? '' : +h2b.toFixed(1) } }];

const t = $('Normalize Alert Payload').first().json;
const c = $input.first().json;
if (!c.client_id) return [{ json: { ...t, client_found: false } }];
const setpoint = parseFloat(c.critical_temp_celsius);
const limit = parseFloat(c.allowed_threshold_celsius);
const delta = t.sensor_fault ? 0 : +(t.current_temp_celsius - setpoint).toFixed(1);
return [{ json: { ...t, client_found: true,
  company_name: c.company_name, facility_type: c.facility_type, contract_tier: c.contract_tier,
  contract_sla_hours: parseFloat(c.contract_sla_hours) || 12,
  critical_temp_celsius: setpoint, allowed_threshold_celsius: limit,
  default_certification: c.default_certification || '', service_zone: c.service_zone || '',
  emergency_contact_phone: c.emergency_contact_phone, site_address: c.site_address,
  temp_delta_celsius: delta,
  threshold_breached: !t.sensor_fault && t.current_temp_celsius > limit
}}];

const b = $('Receive ColdChain Alert').first().json.body || {};
const now = new Date();
const temp = parseFloat(b.current_temp_celsius);
const sensorFault = b.sensor_fault === true || String(b.sensor_fault).toLowerCase() === 'true';
return [{ json: {
  ticket_id: 'TCK-' + now.getTime().toString().slice(-7),
  timestamp_in: now.toISOString(),
  source: b.source || 'WEBHOOK',
  client_id: String(b.client_id || '').trim().toUpperCase(),
  equipment_type: b.equipment_type || 'Unknown',
  current_temp_celsius: temp,
  temp_rate_c_per_hr: parseFloat(b.temp_rate_c_per_hr) || 0,
  alarm_code: b.alarm_code || '',
  defrost_active: b.defrost_active === true || String(b.defrost_active).toLowerCase() === 'true',
  product_class: String(b.product_class || 'GENERAL').toUpperCase(),
  sensor_fault: sensorFault,
  notes: b.notes || '',
  valid: !!b.client_id && (Number.isFinite(temp) || sensorFault)
}}];
